<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Когда аванс попадает под казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Когда контракт по источнику и сумме входит в перечень статьи 5 Закона № 426-ФЗ: авансы по госконтрактам от 100 млн ₽, авансы соисполнителей свыше 3 млн ₽, авансы по контрактам за счёт субсидий, авансы по ГОЗ свыше 3 млн ₽."}}, {"@type": "Question", "name": "Какой размер аванса можно получить при казначейском сопровождении?", "acceptedAnswer": {"@type": "Answer", "text": "Для федеральных нужд конструкция задана пунктом 18 Положения № 1496: базовый предел — 30% суммы контракта, а свыше 30 и не более 90% допускается при включении в контракт условия о казначейском сопровождении аванса. Отдельные абзацы пункта 18 Правительство приостанавливало на конкретные годы, поэтому предельный размер сверяют с актом текущего года и документацией закупки."}}, {"@type": "Question", "name": "Куда перечисляется аванс под сопровождением?", "acceptedAnswer": {"@type": "Answer", "text": "На лицевой счёт исполнителя в территориальном органе казначейства (счёт 71), а не на банковский расчётный счёт. Расходование идёт под санкционирование каждого платежа."}}, {"@type": "Question", "name": "Нужно ли обеспечение при авансе?", "acceptedAnswer": {"@type": "Answer", "text": "По общему правилу да: если контрактом предусмотрен аванс, обеспечение устанавливается не менее его размера, а при авансе свыше 30% начальной (максимальной) цены — в размере аванса. Но если расчёты в части выплаты аванса подлежат казначейскому сопровождению, действует пункт 3 части 6 статьи 96: обеспечение считается от начальной (максимальной) цены, уменьшенной на размер аванса."}}, {"@type": "Question", "name": "Можно ли потратить аванс на любые расходы?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Только на цели, связанные с исполнением контракта и заранее отражённые в сведениях об операциях с целевыми средствами. Нецелевые платежи казначейство возвращает."}}, {"@type": "Question", "name": "Что такое казначейское обеспечение обязательств?", "acceptedAnswer": {"@type": "Answer", "text": "Альтернатива «живому» авансу: вместо денег на счёт исполнитель получает казначейское обеспечение, а оплата соисполнителям проходит через казначейство под фактическую поставку. Регулируется статьёй 242.22 БК и статьёй 5 Закона № 426-ФЗ."}}, {"@type": "Question", "name": "Почему казначейство вернуло платёж с аванса?", "acceptedAnswer": {"@type": "Answer", "text": "Чаще всего — расход не отражён в сведениях об операциях, неверное назначение платежа или код, отсутствует документ-основание либо расход не связан с контрактом."}}, {"@type": "Question", "name": "Когда открывать лицевой счёт под аванс?", "acceptedAnswer": {"@type": "Answer", "text": "До подписания контракта или до даты перечисления аванса. Без открытого счёта 71 заказчик не сможет перечислить предоплату под сопровождением."}}, {"@type": "Question", "name": "Чем аванс под казначейское сопровождение отличается от обычной предоплаты?", "acceptedAnswer": {"@type": "Answer", "text": "Обычный аванс идёт на банковский счёт и расходуется свободно. Аванс под казначейским сопровождением зачисляется на лицевой счёт в ТОФК и тратится только под санкционирование, по целевому назначению, отражённому в сведениях об операциях."}}, {"@type": "Question", "name": "Может ли заказчик вообще не требовать обеспечение исполнения контракта?", "acceptedAnswer": {"@type": "Answer", "text": "Да, если расчёты по контракту подлежат казначейскому сопровождению. По части 6.1 статьи 96 Закона № 44-ФЗ заказчик вправе не устанавливать такое требование, а если устанавливает — размер не превышает 10 процентов начальной (максимальной) цены контракта."}}, {"@type": "Question", "name": "Правда ли, что в 2026 году аванс могут перечислить на расчётный счёт в банке?", "acceptedAnswer": {"@type": "Answer", "text": "Да, в случаях, названных частями 2–5 и 8 статьи 15 Федерального закона от 28.11.2025 № 431-ФЗ. Действие подпункта 1 пункта 2 и пункта 5 статьи 242.23 Бюджетного кодекса приостановлено с 01.01.2025 до 01.01.2027 в части открытия поставщикам лицевых счетов, а пункта 3 — в части запрета перечислять средства на расчётные счета. Оплата идёт на счёт в банке в порядке, установленном Правительством."}}, {"@type": "Question", "name": "Как перечисляется аванс на строительные материалы и оборудование?", "acceptedAnswer": {"@type": "Answer", "text": "По этой группе контрактов аванс перечисляется на основании перечня материалов и оборудования, включённых в проектную документацию, представленного в территориальный орган казначейства по форме Правительства. Для поставщиков материалов из перечня Минстроя России есть дополнительное условие: закупка в электронной форме на электронной площадке либо на организованных торгах."}}, {"@type": "Question", "name": "Кто возвращает аванс, если исполнитель ликвидирован?", "acceptedAnswer": {"@type": "Answer", "text": "Федеральное казначейство — по обращению государственного заказчика, в порядке, который оно же утверждает (подпункт 1 пункта 4.3 статьи 242.23 Бюджетного кодекса). Деньги уходят в федеральный бюджет, если год отчётный, либо на лицевой счёт заказчика, если текущий."}}, {"@type": "Question", "name": "Нужен ли лицевой счёт под аванс по договору аренды или за коммунальные услуги?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Средства по договорам аренды, коммунальных услуг, электроэнергии, услуг связи, страхования и по ряду других предметов не подлежат казначейскому сопровождению по статье 242.27 Бюджетного кодекса, а платёж такому контрагенту с лицевого счёта прямо разрешён исключением подпункта 4 пункта 3 статьи 242.23."}}, {"@type": "Question", "name": "Когда уменьшается обеспечение при сопровождаемом авансе?", "acceptedAnswer": {"@type": "Answer", "text": "По части 7.3 статьи 96 — после приёмки результата в объёме, превышающем выплаченный аванс, и при отсутствии у заказчика неисполненных требований об уплате неустоек. По обычному контракту достаточно приёмки в объёме аванса."}}, {"@type": "Question", "name": "Можно ли вывести аванс как прибыль до выполнения работ?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Средства аванса на лицевом счёте целевые: ими нельзя закрыть кассовый разрыв по другому контракту или вывести как прибыль до отработки. Допустимы только расходы по исполнению этого контракта."}}, {"@type": "Question", "name": "Даёт ли постановление № 901 право на аванс 70 процентов?", "acceptedAnswer": {"@type": "Answer", "text": "Нет, если вы не публично-правовая компания «Единый заказчик в сфере строительства». Постановление Правительства РФ от 17.07.2026 № 901 — индивидуальный акт: пункт 1 разрешает аванс до 70 процентов цены одного конкретного контракта от 05.09.2022 № 0995400000222000066 (реестровый номер 1770744825522000089) и не более доведённых лимитов бюджетных обязательств, пункт 2 позволяет внести в этот контракт изменение об увеличении аванса по части 1 статьи 111 Закона № 44-ФЗ. Общего правила об авансировании акт не вводит, ссылаться на него в своей закупке нельзя."}}]}
</script>
