{"@context": "https://schema.org", "@type": "HowTo", "name": "Как получить и отработать аванс при казначейском сопровождении", "step": [{"@type": "HowToStep", "position": 1, "name": "Подтвердите попадание под казначейское сопровождение", "text": "Сверьте контракт с перечнем статьи 5 Закона № 426-ФЗ по источнику средств и сумме контракта."}, {"@type": "HowToStep", "position": 2, "name": "Откройте лицевой счёт в ТОФК", "text": "Без лицевого счёта (счёт 71) заказчик не перечислит аванс под казначейским сопровождением."}, {"@type": "HowToStep", "position": 3, "name": "Согласуйте размер аванса и обеспечение", "text": "Проверьте проект контракта: предельный размер предоплаты и требуемое обеспечение исполнения по 44-ФЗ."}, {"@type": "HowToStep", "position": 4, "name": "Утвердите сведения об операциях", "text": "Распишите целевые направления расходования аванса — это план будущих платежей, по которому идёт санкционирование."}, {"@type": "HowToStep", "position": 5, "name": "Получите аванс на лицевой счёт", "text": "Заказчик перечисляет предоплату на лицевой счёт в территориальном органе казначейства."}, {"@type": "HowToStep", "position": 6, "name": "Расходуйте под санкционирование", "text": "На каждый платёж формируйте распоряжение и прикладывайте документы-основания; казначейство санкционирует целевые расходы."}, {"@type": "HowToStep", "position": 7, "name": "Закрывайте аванс по факту работ", "text": "Отражайте отработку аванса в актах и отчётности по контракту."}]}
</script>
